Here is a Python implementation of the Template Method pattern for sorting:

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = list(data)

    # Template Method
    def sort(self):
        self._sort()
        return self.data

    @abstractmethod
    def _sort(self):
        """Algorithm specific sorting steps"""
        pass

    # Primitive operations used by the template
    def compare(self, a, b):
        return a > b

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]


class BubbleSort(SortAlgorithm):
    def _sort(self):
        n = len(self.data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]):
                    self.swap(j, j + 1)


class SelectionSort(SortAlgorithm):
    def _sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[min_idx], self.data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    ints = [5, 2, 9, 1, 5, 6]
    strs = ["banana", "apple", "cherry", "date"]

    bubble_int = BubbleSort(ints)
    print("BubbleSort ints:", bubble_int.sort())

    selection_int = SelectionSort(ints)
    print("SelectionSort ints:", selection_int.sort())

    bubble_str = BubbleSort(strs)
    print("BubbleSort strs:", bubble_str.sort())

    selection_str = SelectionSort(strs)
    print("SelectionSort strs:", selection_str.sort())
```

`SortAlgorithm.sort()` is the template method that defines the skeleton. The concrete subclasses `BubbleSort` and `SelectionSort` provide their own `_sort` implementation while reusing the common `compare` and `swap` primitive operations.
